-- after the owner picks @target (MP proposal: 10119 'ROUND OFF', the only round-off account) and CFG-05 has re-pointed the charge
DECLARE @missing int = 424, @target int = (SELECT TOP 1 Act_Id FROM IQAccmst WHERE Act_Cat='A' AND ISNULL(Act_Usage,0)=0 AND REPLACE(Act_Name,' ','') LIKE 'roundoff%' ORDER BY Act_Id DESC);
UPDATE IQDayBook SET Act_ID=@target WHERE Act_ID=@missing AND @target IS NOT NULL;
UPDATE IQDoc_Chrgs SET Act_ID=@target WHERE Act_ID=@missing AND @target IS NOT NULL

DELETE cs FROM IQCHRGSETS cs JOIN IQCHRGSETMST m ON m.Set_no=cs.Set_No WHERE m.Set_name LIKE 'MK Core%' AND NOT EXISTS (SELECT 1 FROM TTypes tt WHERE tt.vousetno=m.Set_no);
DELETE m FROM IQCHRGSETMST m WHERE m.Set_name LIKE 'MK Core%' AND NOT EXISTS (SELECT 1 FROM TTypes tt WHERE tt.vousetno=m.Set_no);
DELETE c FROM IQCHARGES c WHERE c.Chrg_Name LIKE 'MK Core%' AND NOT EXISTS (SELECT 1 FROM IQCHRGSETS cs WHERE cs.chrg_Id=c.Chrg_Id) AND NOT EXISTS (SELECT 1 FROM IQDoc_Chrgs dc WHERE dc.Chrg_id=c.Chrg_Id)
